class PromoRegistry:
    """In-memory storage of promo codes and their usage counters.

    ``customer_id`` is compared as given (no normalization): ``"acc-1"`` and ``"ACC-1"``
    are different customers.
    """

    def __init__(self, clock: Clock) -> None:
        self._clock = clock
        self._promos: dict[str, PromoCode] = {}
        self._uses: dict[str, int] = {}
        self._customer_uses: dict[tuple[str, str], int] = {}

    def add(self, promo: PromoCode) -> None:
        if promo.code in self._promos:
            raise ValidationError(f"duplicate promo code: {promo.code}")
        self._promos[promo.code] = promo
        self._uses[promo.code] = 0

    def resolve(self, code: str, customer_id: str | None = None) -> PromoCode:
        """Find the promo code and check existence, validity period and usage limits."""
        _check_customer_id(customer_id)
        promo = self._get(code)
        now = self._clock.now()
        if (promo.starts_at is not None and now < promo.starts_at) or (
            promo.expires_at is not None and now >= promo.expires_at
        ):
            raise PromoExpiredError(f"promo code {promo.code} is not valid now")
        if promo.max_uses is not None and self._uses[promo.code] >= promo.max_uses:
            raise PromoConditionsError(f"promo code {promo.code} has no uses left")
        if promo.max_uses_per_customer is not None:
            if customer_id is None:
                raise PromoConditionsError(f"promo code {promo.code} requires a customer")
            used = self._customer_uses.get((promo.code, customer_id), 0)
            if used >= promo.max_uses_per_customer:
                raise PromoConditionsError(
                    f"promo code {promo.code} has no uses left for this customer"
                )
        return promo

    def record_use(self, code: str, customer_id: str | None = None) -> None:
        """Count one successful use; the code must still pass :meth:`resolve`."""
        promo = self.resolve(code, customer_id)
        self._uses[promo.code] += 1
        if customer_id is not None:
            key = (promo.code, customer_id)
            self._customer_uses[key] = self._customer_uses.get(key, 0) + 1

    def release_use(self, code: str, customer_id: str | None = None) -> None:
        """Give back one use (e.g. after cancellation). Counters never go below zero."""
        _check_customer_id(customer_id)
        promo = self._get(code)
        self._uses[promo.code] = max(0, self._uses[promo.code] - 1)
        if customer_id is not None:
            key = (promo.code, customer_id)
            self._customer_uses[key] = max(0, self._customer_uses.get(key, 0) - 1)

